 */

import {
  chromium,
  type Browser,
  type BrowserContext,
  type Page,
  type BrowserType,
} from '@playwright/test';
import type { Config } from '../config/config.js';
import { ApprovalMode } from '../config/config.js';
import type {
  ToolCallConfirmationDetails,
  ToolInvocation,
  ToolResult,
} from './tools.js';
import {
  BaseDeclarativeTool,
  BaseToolInvocation,
  Kind,
  ToolConfirmationOutcome,
} from './tools.js';
import { ToolErrorType } from './tool-error.js';

// Default configuration values
const DEFAULT_NAVIGATION_TIMEOUT = 30000;
const DEFAULT_ACTION_TIMEOUT = 15000;
const DEFAULT_MAX_PAGES = 10;
const DEFAULT_MAX_SCREENSHOT_SIZE = 5 * 1024 * 1024; // 5MB

/**
 * Browser control configuration interface
 */
export interface BrowserControlConfig {
  headless?: boolean;
  slowMo?: number;
  devtools?: boolean;
  navigationTimeout?: number;
  actionTimeout?: number;
  maxPagesPerSession?: number;
  maxScreenshotSize?: number;
  allowedOrigins?: string[];
  blockExternal?: boolean;
  sandbox?: boolean;
}

/**
 * Parameters for the BrowserControl tool
 */
export interface BrowserControlParams {
  /**
   * The browser operation to perform
   */
  operation: string;
  /**
   * Operation-specific parameters
   */
  params?: Record<string, unknown>;
}

/**
 * Result from browser control operations
 */
export interface BrowserControlResult extends ToolResult {
  /**
   * Current page URL
   */
  pageUrl?: string;
  /**
   * Current page title
   */
  pageTitle?: string;
  /**
   * Path to saved screenshot (if any)
   */
  screenshotPath?: string;
  /**
   * Base64-encoded screenshot data
   */
  screenshot?: string;
  /**
   * Result value from JavaScript evaluation
   */
  value?: unknown;
  /**
   * Cookies from getCookies operation
   */
  cookies?: unknown[];
  /**
   * Locator result for element selection operations
   */
  locator?: string;
}

/**
 * Browser session manager - handles browser lifecycle
 */
class BrowserSession {
  private browser: Browser | null = null;
  private context: BrowserContext | null = null;
  private page: Page | null = null;
  private config: BrowserControlConfig;
  private browserType: BrowserType;

  constructor(config: BrowserControlConfig) {
    this.config = config;
    this.browserType = chromium;
  }

  async ensureInitialized(): Promise<void> {
    if (!this.browser) {
      const launchOptions: Record<string, unknown> = {
        headless: this.config.headless ?? true,
        slowMo: this.config.slowMo ?? 0,
        args: [],
      };

      // Add sandbox args if needed
      if (this.config.sandbox === false) {
        launchOptions.args.push('--no-sandbox', '--disable-setuid-sandbox', '--no-zygote');
      }

      this.browser = await this.browserType.launch(launchOptions);
    }

    if (!this.context) {
      this.context = await this.browser.newContext();
    }

    if (!this.page) {
      this.page = await this.context.newPage();
    }
  }

  getPage(): Page | null {
    return this.page;
  }

  getContext(): BrowserContext | null {
    return this.context;
  }

  getBrowser(): Browser | null {
    return this.browser;
  }

  async close(): Promise<void> {
    if (this.page) {
      await this.page.close().catch(() => {});
      this.page = null;
    }

    if (this.context) {
      await this.context.close().catch(() => {});
      this.context = null;
    }

    if (this.browser) {
      await this.browser.close().catch(() => {});
      this.browser = null;
    }
  }

  async reset(): Promise<void> {
    await this.close();
    await this.ensureInitialized();
  }
}

// Global browser session (shared across invocations)
let globalSession: BrowserSession | null = null;

/**
 * Implementation of the BrowserControl tool invocation logic
 */
class BrowserControlToolInvocation extends BaseToolInvocation<
  BrowserControlParams,
  BrowserControlResult
> {
  private readonly config: Config;
  private readonly browserConfig: BrowserControlConfig;

  constructor(config: Config, params: BrowserControlParams) {
    super(params);
    this.config = config;
    this.browserConfig = this.getBrowserConfig();
  }

  private getBrowserConfig(): BrowserControlConfig {
    // Try to get from Config, otherwise use defaults
    const browserControlConfig = (this.config as unknown as { browserControl?: BrowserControlConfig }).browserControl;
    return {
      headless: browserControlConfig?.headless ?? true,
      slowMo: browserControlConfig?.slowMo ?? 0,
      devtools: browserControlConfig?.devtools ?? false,
      navigationTimeout: browserControlConfig?.navigationTimeout ?? DEFAULT_NAVIGATION_TIMEOUT,
      actionTimeout: browserControlConfig?.actionTimeout ?? DEFAULT_ACTION_TIMEOUT,
      maxPagesPerSession: browserControlConfig?.maxPagesPerSession ?? DEFAULT_MAX_PAGES,
      maxScreenshotSize: browserControlConfig?.maxScreenshotSize ?? DEFAULT_MAX_SCREENSHOT_SIZE,
      allowedOrigins: browserControlConfig?.allowedOrigins,
      blockExternal: browserControlConfig?.blockExternal ?? false,
      sandbox: browserControlConfig?.sandbox ?? true,
    };
  }

  private getSession(): BrowserSession {
    if (!globalSession) {
      globalSession = new BrowserSession(this.browserConfig);
    }
    return globalSession;
  }

  private isUrlAllowed(url: string): boolean {
    const allowedOrigins = this.browserConfig.allowedOrigins;

    if (!allowedOrigins || allowedOrigins.length === 0) {
      return true; // No restrictions
    }

    try {
      const parsed = new URL(url);
      const origin = `${parsed.protocol}//${parsed.host}`;
      return allowedOrigins.some(
        (allowed) =>
          origin === allowed || origin.endsWith(`.${allowed}`)
      );
    } catch {
      return false;
    }
  }

  async execute(signal: AbortSignal): Promise<BrowserControlResult> {
    const operation = this.params.operation;
    const opParams = this.params.params || {};

    try {
      // Initialize browser session for most operations
      if (operation !== 'close') {
        const session = this.getSession();
        await session.ensureInitialized();
      }

      switch (operation) {
        case 'goto':
          return await this.executeGoto(opParams);
        case 'reload':
          return await this.executeReload(opParams);
        case 'goBack':
          return await this.executeGoBack(opParams);
        case 'goForward':
          return await this.executeGoForward(opParams);
        case 'locator':
          return await this.executeLocator(opParams);
        case 'getByRole':
          return await this.executeGetByRole(opParams);
        case 'getByText':
          return await this.executeGetByText(opParams);
        case 'getByLabel':
          return await this.executeGetByLabel(opParams);
        case 'getByPlaceholder':
          return await this.executeGetByPlaceholder(opParams);
        case 'getByAltText':
          return await this.executeGetByAltText(opParams);
        case 'getByTitle':
          return await this.executeGetByTitle(opParams);
        case 'getByTestId':
          return await this.executeGetByTestId(opParams);
        case 'fill':
          return await this.executeFill(opParams);
        case 'type':
          return await this.executeType(opParams);
        case 'clear':
          return await this.executeClear(opParams);
        case 'check':
          return await this.executeCheck(opParams);
        case 'uncheck':
          return await this.executeUncheck(opParams);
        case 'selectOption':
          return await this.executeSelectOption(opParams);
        case 'click':
          return await this.executeClick(opParams);
        case 'dblclick':
          return await this.executeDblClick(opParams);
        case 'evaluate':
          return await this.executeEvaluate(opParams);
        case 'evaluateHandle':
          return await this.executeEvaluateHandle(opParams);
        case 'screenshot':
          return await this.executeScreenshot(opParams);
        case 'close':
          return await this.executeClose();
        case 'newPage':
          return await this.executeNewPage(opParams);
        case 'getCookies':
          return await this.executeGetCookies(opParams);
        case 'setCookie':
          return await this.executeSetCookie(opParams);
        case 'acceptDialog':
          return await this.executeAcceptDialog();
        case 'dismissDialog':
          return await this.executeDismissDialog();
        default:
          throw new Error(`Unknown operation: ${operation}`);
      }
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      return {
        llmContent: `Error: ${errorMessage}`,
        returnDisplay: `Error: ${errorMessage}`,
        error: {
          message: errorMessage,
          type: ToolErrorType.EXECUTION_FAILED,
        },
      };
    }
  }

  private async executeGoto(params: Record<string, unknown>): Promise<BrowserControlResult> {
    const url = params.url as string;
    if (!url) {
      throw new Error('URL is required for goto operation');
    }

    if (!this.isUrlAllowed(url)) {
      throw new Error(`URL not allowed: ${url}. Check allowedOrigins configuration.`);
    }

    const session = this.getSession();
    const page = session.getPage();
    if (!page) {
      throw new Error('No page available');
    }

    const waitUntil = (params.waitUntil as 'load' | 'domcontentloaded' | 'networkidle') || 'load';
    const timeout = (params.timeout as number) || this.browserConfig.navigationTimeout;

    await page.goto(url, { waitUntil, timeout });

    return this.createPageResult(`Navigated to ${url}`);
  }

