    }

    const waitUntil = (params.waitUntil as 'load' | 'domcontentloaded') || 'load';
    const timeout = (params.timeout as number) || this.browserConfig.navigationTimeout;

    await page.reload({ waitUntil, timeout });

    return this.createPageResult('Page reloaded');
  }

