  private async executeScreenshot(params: Record<string, unknown>): Promise<BrowserControlResult> {
    const session = this.getSession();
    const page = session.getPage();
    if (!page) {
      throw new Error('No page available');
    }

    const screenshotOptions: Record<string, unknown> = {};

    if (params.type) screenshotOptions.type = params.type;
    if (params.quality) screenshotOptions.quality = params.quality;
    if (params.fullPage) screenshotOptions.fullPage = params.fullPage;
    if (params.clip) screenshotOptions.clip = params.clip;
    if (params.omitBackground) screenshotOptions.omitBackground = params.omitBackground;

    const screenshotBuffer = await page.screenshot(screenshotOptions);
    const screenshotBase64 = screenshotBuffer.toString('base64');
    const mimeType = params.type === 'jpeg' ? 'image/jpeg' : 'image/png';
    const dataUri = `data:${mimeType};base64,${screenshotBase64}`;

    // Check size limit
    if (screenshotBuffer.length > this.browserConfig.maxScreenshotSize) {
      throw new Error(`Screenshot exceeds size limit of ${this.browserConfig.maxScreenshotSize} bytes`);
    }

    return {
      llmContent: `Screenshot captured (${screenshotBuffer.length} bytes)`,
      returnDisplay: `Screenshot captured (${screenshotBuffer.length} bytes)`,
      screenshot: dataUri,
    };
