      throw new Error(`URL not allowed: ${url}. Check allowedOrigins configuration.`);
    }

    const session = this.getSession();
    const page = session.getPage();
    if (!page) {
      throw new Error('No page available');
    }

    const waitUntil = (params.waitUntil as 'load' | 'domcontentloaded' | 'networkidle') || 'load';
    const timeout = (params.timeout as number) || this.browserConfig.navigationTimeout;

    await page.goto(url, { waitUntil, timeout });

    return this.createPageResult(`Navigated to ${url}`);
