  private async executeNewPage(params: Record<string, unknown>): Promise<BrowserControlResult> {
    const session = this.getSession();
    const context = session.getContext();
    if (!context) {
      throw new Error('No browser context available');
    }

    const url = params.url as string;
    const newPage = await context.newPage();

    if (url) {
      if (!this.isUrlAllowed(url)) {
        throw new Error(`URL not allowed: ${url}. Check allowedOrigins configuration.`);
      }
      await newPage.goto(url, { timeout: this.browserConfig.navigationTimeout });
    }

    // Update the session's page reference
    // Note: This is a simplification - in a full implementation we'd track multiple pages
    (session as unknown as { page: Page }).page = newPage;

    return this.createPageResult(`New page opened${url ? ` and navigated to ${url}` : ''}`);
