  private async executeSetCookie(params: Record<string, unknown>): Promise<BrowserControlResult> {
    const session = this.getSession();
    const context = session.getContext();
    if (!context) {
      throw new Error('No browser context available');
    }

    const name = params.name as string;
    const value = params.value as string;
    if (!name || !value) {
      throw new Error('Name and value are required for setCookie operation');
    }

    const cookie: Record<string, unknown> = { name, value };
    if (params.url) cookie.url = params.url;
    if (params.domain) cookie.domain = params.domain;
    if (params.path) cookie.path = params.path;
    if (params.expires) cookie.expires = params.expires;
    if (params.httpOnly) cookie.httpOnly = params.httpOnly;
    if (params.secure) cookie.secure = params.secure;
    if (params.sameSite) cookie.sameSite = params.sameSite;

    await context.addCookies([cookie as Parameters<typeof context.addCookies>[0]]);

    return {
      llmContent: `Cookie set: ${name}`,
      returnDisplay: `Cookie set: ${name}`,
    };
  }

  private async executeAcceptDialog(): Promise<BrowserControlResult> {
    const session = this.getSession();
    const page = session.getPage();
    if (!page) {
      throw new Error('No page available');
